export const scienceQuestionId=(l,q)=>'science:'+l.id+':'+q.id;
export const scienceReviewItems=scienceLessons.flatMap(l=>l.questions.map(q=>({...q,id:scienceQuestionId(l,q),questionId:q.id,kind:'science',label:l.title,lessonId:l.id})));
export function normalizeScience(raw){const out={current:scienceLessons.some(l=>l.id===raw?.current)?raw.current:null,wordsMet:[...new Set((Array.isArray(raw?.wordsMet)?raw.wordsMet:[]).filter(w=>scienceLessons.some(l=>l.words.some(v=>v.word===w))))],lessons:{}};for(const l of scienceLessons){const p=raw?.lessons?.[l.id];if(!p)continue;const steps=scienceSteps(l),answers={},attempts={},experiments={};for(const q of l.questions){if(q.choices.some(c=>c.id===p.answers?.[q.id]))answers[q.id]=p.answers[q.id];const a=p.attempts?.[q.id];if(a)attempts[q.id]={tries:Number.isInteger(a.tries)&&a.tries>=0?Math.min(10000,a.tries):0,misses:Number.isInteger(a.misses)&&a.misses>=0?Math.min(10000,a.misses):0,assisted:a.assisted===true,firstCorrect:typeof a.firstCorrect==='boolean'?a.firstCorrect:null};}for(const s of l.sentences.filter(s=>s.action)){const e=p.experiments?.[s.action.id];if(e&&s.action.options.some(o=>o.id===e.value))experiments[s.action.id]={value:e.value,tried:[...new Set((Array.isArray(e.tried)?e.tried:[]).filter(id=>s.action.options.some(o=>o.id===id)))]};}out.lessons[l.id]={step:Number.isInteger(p.step)&&p.step>=0&&p.step<steps.length?p.step:0,done:p.done===true,answers,attempts,experiments,completed:[...new Set((Array.isArray(p.completed)?p.completed:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<steps.length))]};}return out;}
const demo=q=>'Let’s look together. '+q.feedback.replace(/^Yes!\s*/,'')+' Try again.';
export const scienceAudioSpecs=[...new Map(scienceLessons.flatMap(l=>[
 ...l.words.flatMap(w=>[{key:'science-word:'+w.word,text:w.word},{key:'text:'+w.text,text:w.text}]),
 ...[...l.sentences,l.recap].flatMap(s=>[{key:'text:'+s.text,text:s.text},...(s.action?.options.map(o=>({key:'text:'+o.text,text:o.text}))||[])]),
 ...l.questions.flatMap(q=>[{key:'text:'+q.prompt,text:q.prompt},{key:'science-feedback:'+scienceQuestionId(l,q),text:q.feedback},{key:'science-hint:'+scienceQuestionId(l,q),text:q.hint},{key:'science-demo:'+scienceQuestionId(l,q),text:demo(q)}])
]).map(s=>[s.key,{...s,voice:'en-GB-SoniaNeural',rate:'-12%'}])).values()];
